typedef struct {
  float diametro;
  float perimetro;
  float area;
} TCirculo;

TCirculo calcularCirculo(float radio) {
  TCirculo c;

  c.diametro = radio * 2;
  c.perimetro = 2 * 3.14 * radio;
  c.area = 3.14 * radio * radio;
  return c;
}

typedef struct {
  int horas;
  int minutos;
  int segundos;
} TTiempo;

TTiempo descomponer(int total) {
  TTiempo t;

  t.horas = total / 3600;
  t.minutos = (total % 3600) / 60;
  t.segundos = total % 60;
  return t;
}
